// ─── Supabase Config ──────────────────────────────────────────────────────────
const SUPABASE_URL = "https://urkbbwsxgwlsihqmvcna.supabase.co";
const SUPABASE_KEY = "sb_publishable_FakMrj_v7Q9Ct5noBUpVfw_RCvOnGG9";

const sb = async (path, opts = {}) => {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
    headers: {
      "apikey": SUPABASE_KEY,
      "Authorization": `Bearer ${SUPABASE_KEY}`,
      "Content-Type": "application/json",
      "Prefer": opts.prefer || "return=representation",
      ...opts.headers,
    },
    ...opts,
  });
  if (!res.ok) {
    const err = await res.text();
    throw new Error(err);
  }
  const text = await res.text();
  return text ? JSON.parse(text) : [];
};

const api = {
  // Users
  getUsers: () => sb("users?order=created_at"),
  createUser: (d) => sb("users", { method: "POST", body: JSON.stringify(d) }),
  updateUser: (id, d) => sb(`users?id=eq.${id}`, { method: "PATCH", body: JSON.stringify(d) }),
  deleteUser: (id) => sb(`users?id=eq.${id}`, { method: "DELETE", prefer: "return=minimal" }),
  loginUser: (username, password) => sb(`users?username=eq.${encodeURIComponent(username)}&password=eq.${encodeURIComponent(password)}`),

  // Categories
  getCategories: () => sb("categories?order=name"),
  createCategory: (name) => sb("categories", { method: "POST", body: JSON.stringify({ name }) }),
  deleteCategory: (id) => sb(`categories?id=eq.${id}`, { method: "DELETE", prefer: "return=minimal" }),

  // Products
  getProducts: () => sb("products?order=name"),
  createProduct: (d) => sb("products", { method: "POST", body: JSON.stringify(d) }),
  updateProduct: (id, d) => sb(`products?id=eq.${id}`, { method: "PATCH", body: JSON.stringify(d) }),
  deleteProduct: (id) => sb(`products?id=eq.${id}`, { method: "DELETE", prefer: "return=minimal" }),

  // Sales
  getSales: () => sb("sales?order=created_at.desc"),
  createSale: (d) => sb("sales", { method: "POST", body: JSON.stringify(d) }),
};

