const injectStyles = () => {
  if (document.getElementById("dv3-styles")) return;
  const s = document.createElement("style");
  s.id = "dv3-styles";
  s.textContent = `
    @import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=DM+Sans:wght@300;400;500;600;700&display=swap');
    *{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent;}
    body{background:${G.bg};color:${G.text};font-family:'DM Sans',sans-serif;min-height:100vh;overflow-x:hidden;}
    ::-webkit-scrollbar{width:3px;} ::-webkit-scrollbar-track{background:${G.surface};} ::-webkit-scrollbar-thumb{background:${G.border};border-radius:2px;}
    input,select,textarea{font-family:'DM Sans',sans-serif;outline:none;border:none;background:transparent;}
    button{font-family:'DM Sans',sans-serif;cursor:pointer;border:none;outline:none;}
    @keyframes fadeUp{from{opacity:0;transform:translateY(20px);}to{opacity:1;transform:translateY(0);}}
    @keyframes fadeIn{from{opacity:0;}to{opacity:1;}}
    @keyframes slideUp{from{transform:translateY(100%);}to{transform:translateY(0);}}
    @keyframes toastIn{from{opacity:0;transform:translateY(80px) scale(0.9);}to{opacity:1;transform:translateY(0) scale(1);}}
    @keyframes spin{to{transform:rotate(360deg);}}
    .fade-up{animation:fadeUp 0.45s cubic-bezier(0.16,1,0.3,1) both;}
    .fade-in{animation:fadeIn 0.3s ease both;}
    .btn-press:active{transform:scale(0.95);transition:transform 0.1s;}
    .spin{animation:spin 0.8s linear infinite;}
  `;
  document.head.appendChild(s);
};

const fmt = (n) => `${Number(n || 0).toLocaleString("fr-SN")} FCFA`;
const uid = () => Math.random().toString(36).slice(2, 9);

// ─── Toast ────────────────────────────────────────────────────────────────────
let toastFn = null;
const Toast = () => {
  const [toasts, setToasts] = useState([]);
  toastFn = useCallback((msg, type = "success") => {
    const id = uid();
    setToasts(p => [...p, { id, msg, type }]);
    setTimeout(() => setToasts(p => p.filter(t => t.id !== id)), 3200);
  }, []);
  const colors = { success: G.green, error: G.danger, warn: G.warning, info: G.info };
  return (
    <div style={{ position: "fixed", bottom: 90, left: "50%", transform: "translateX(-50%)", zIndex: 9999, display: "flex", flexDirection: "column", gap: 8, alignItems: "center", width: "92vw", maxWidth: 380, pointerEvents: "none" }}>
      {toasts.map(t => (
        <div key={t.id} style={{ background: colors[t.type] || G.green, color: ["error","info"].includes(t.type) ? "#fff" : "#000", padding: "12px 20px", borderRadius: 14, fontWeight: 700, fontSize: 14, animation: "toastIn 0.35s cubic-bezier(0.16,1,0.3,1)", boxShadow: "0 12px 40px rgba(0,0,0,0.5)", width: "100%", textAlign: "center" }}>
          {t.type === "success" ? "✓ " : t.type === "error" ? "✕ " : "⚠ "}{t.msg}
        </div>
      ))}
    </div>
  );
};
const toast = (msg, type) => toastFn?.(msg, type);

