const Btn = ({ children, onClick, variant = "primary", style = {}, disabled, full, sm, loading }) => {
  const variants = {
    primary: { background: `linear-gradient(135deg,${G.green},${G.greenDim})`, color: "#000", boxShadow: `0 4px 24px ${G.greenGlow}` },
    ghost: { background: G.greenSoft, color: G.green, border: `1px solid ${G.border}` },
    danger: { background: "rgba(239,68,68,0.12)", color: G.danger, border: "1px solid rgba(239,68,68,0.25)" },
    surface: { background: G.card, color: G.text, border: `1px solid ${G.border}` },
  };
  return (
    <button className="btn-press" onClick={disabled || loading ? undefined : onClick}
      style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, padding: sm ? "8px 14px" : "13px 22px", borderRadius: sm ? 10 : 14, fontWeight: 600, fontSize: sm ? 13 : 15, transition: "all 0.18s", width: full ? "100%" : "auto", opacity: (disabled || loading) ? 0.5 : 1, cursor: (disabled || loading) ? "not-allowed" : "pointer", ...variants[variant], ...style }}>
      {loading ? <Spinner size={18} /> : children}
    </button>
  );
};

