// ─── Login ────────────────────────────────────────────────────────────────────
const Login = ({ onLogin }) => {
  const [u, setU] = useState(""); const [p, setP] = useState("");
  const [err, setErr] = useState(""); const [loading, setLoading] = useState(false);
  const submit = async () => {
    if (!u || !p) { setErr("Veuillez remplir tous les champs."); return; }
    setLoading(true); setErr("");
    try {
      const res = await api.loginUser(u.trim(), p);
      if (res && res.length > 0) onLogin(res[0]);
      else setErr("Identifiants invalides. Réessayez.");
    } catch { setErr("Erreur de connexion. Vérifiez votre connexion internet."); }
    setLoading(false);
  };
  return (
    <div style={{ minHeight: "100vh", background: G.bg, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: 28, position: "relative", overflow: "hidden" }}>
      <div style={{ position: "absolute", top: -80, right: -80, width: 280, height: 280, borderRadius: "50%", background: G.greenGlow, filter: "blur(80px)" }} />
      <div className="fade-up" style={{ width: "100%", maxWidth: 380 }}>
        <div style={{ textAlign: "center", marginBottom: 36 }}><Logo height={90} /></div>
        <Card style={{ padding: 28 }}>
          <h2 style={{ fontFamily: "'Bebas Neue',sans-serif", fontWeight: 400, fontSize: 26, marginBottom: 6, letterSpacing: "0.05em" }}>CONNEXION</h2>
          <p style={{ color: G.muted, fontSize: 13, marginBottom: 24 }}>Personnel autorisé uniquement</p>
          <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
            <Input label="Nom d'utilisateur" value={u} onChange={setU} placeholder="ex: amdy" icon="👤" onKeyDown={e => e.key === "Enter" && submit()} />
            <Input label="Mot de passe" value={p} onChange={setP} type="password" placeholder="••••••••" icon="🔒" onKeyDown={e => e.key === "Enter" && submit()} />
            {err && <p style={{ color: G.danger, fontSize: 13 }}>⚠ {err}</p>}
            <Btn onClick={submit} full loading={loading} style={{ marginTop: 8 }}>Se connecter</Btn>
          </div>
        </Card>
      </div>
    </div>
  );
};

