// ─── User Management ─────────────────────────────────────────────────────────
const UserMgmt = ({ users, setUsers, currentUser }) => {
  const [modal, setModal] = useState(false);
  const [editUser, setEditUser] = useState(null);
  const [form, setForm] = useState({ name: "", username: "", password: "", role: "ventes" });
  const [saving, setSaving] = useState(false);
  const [confirm, setConfirm] = useState(null);
  const [delLoading, setDelLoading] = useState(false);
  const setF = (k, v) => setForm(f => ({ ...f, [k]: v }));
  const openAdd = () => { setForm({ name: "", username: "", password: "", role: "ventes" }); setEditUser(null); setModal(true); };
  const openEdit = u => { setForm({ name: u.name, username: u.username, password: u.password, role: u.role }); setEditUser(u); setModal(true); };
  const save = async () => {
    if (!form.name || !form.username || !form.password) { toast("Tous les champs sont requis", "error"); return; }
    setSaving(true);
    try {
      if (editUser) {
        await api.updateUser(editUser.id, form);
        setUsers(u => u.map(x => x.id === editUser.id ? { ...x, ...form } : x));
        toast("Utilisateur mis à jour");
      } else {
        const res = await api.createUser(form);
        setUsers(u => [...u, res[0]]);
        toast("Utilisateur créé");
      }
      setModal(false);
    } catch (e) {
      const msg = e.message.includes("unique") ? "Ce nom d'utilisateur existe déjà" : "Erreur lors de la sauvegarde";
      toast(msg, "error");
    }
    setSaving(false);
  };
  const del = async () => {
    setDelLoading(true);
    try { await api.deleteUser(confirm.id); setUsers(u => u.filter(x => x.id !== confirm.id)); toast("Utilisateur supprimé"); setConfirm(null); }
    catch { toast("Erreur lors de la suppression", "error"); }
    setDelLoading(false);
  };
  return (
    <div style={{ padding: "20px 16px 100px" }}>
      <Modal open={modal} onClose={() => !saving && setModal(false)} title={editUser ? "Modifier Utilisateur" : "Nouvel Utilisateur"}>
        <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
          <Input label="Nom complet" value={form.name} onChange={v => setF("name", v)} placeholder="ex: Fatou Diallo" />
          <Input label="Nom d'utilisateur" value={form.username} onChange={v => setF("username", v)} placeholder="ex: fatou" />
          <Input label="Mot de passe" value={form.password} onChange={v => setF("password", v)} type="password" placeholder="••••••••" />
          <Select label="Rôle" value={form.role} onChange={v => setF("role", v)} options={[{ value: "admin", label: "👑 Admin" }, { value: "ventes", label: "🧑‍💼 Vendeur" }]} />
          <Btn onClick={save} full loading={saving}>{editUser ? "Enregistrer" : "Créer l'utilisateur"}</Btn>
        </div>
      </Modal>
      <Confirm open={!!confirm} message={`Supprimer "${confirm?.name}" définitivement ?`} onYes={del} onNo={() => setConfirm(null)} loading={delLoading} />
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 22 }}>
        <h1 style={{ fontFamily: "'Bebas Neue',sans-serif", fontWeight: 400, fontSize: 26, letterSpacing: "0.05em" }}>ÉQUIPE</h1>
        <Btn sm onClick={openAdd}>+ Ajouter</Btn>
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {users.map(u => (
          <Card key={u.id}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
                <div style={{ width: 48, height: 48, borderRadius: 14, background: G.greenSoft, border: `1px solid ${G.border}`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 22 }}>{u.role === "admin" ? "👑" : "🧑‍💼"}</div>
                <div>
                  <div style={{ fontWeight: 700, fontSize: 15 }}>{u.name}</div>
                  <div style={{ fontSize: 12, color: G.muted, marginBottom: 4 }}>@{u.username}</div>
                  <Badge color={u.role === "admin" ? G.green : G.info}>{u.role === "admin" ? "Admin" : "Vendeur"}</Badge>
                </div>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                <button onClick={() => openEdit(u)} style={{ background: G.greenSoft, border: `1px solid ${G.border}`, color: G.green, borderRadius: 8, padding: "6px 12px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>✏ Modifier</button>
                {u.id !== currentUser.id && <button onClick={() => setConfirm(u)} style={{ background: "rgba(239,68,68,0.08)", border: "1px solid rgba(239,68,68,0.2)", color: G.danger, borderRadius: 8, padding: "6px 12px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>Supprimer</button>}
              </div>
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
};

// ─── Categories ───────────────────────────────────────────────────────────────
const CatMgmt = ({ categories, setCategories, setPage }) => {
  const [newCat, setNewCat] = useState("");
  const [adding, setAdding] = useState(false);
  const [confirm, setConfirm] = useState(null);
  const [delLoading, setDelLoading] = useState(false);
  const add = async () => {
    if (!newCat.trim()) { toast("Entrez un nom", "warn"); return; }
    setAdding(true);
    try {
      const res = await api.createCategory(newCat.trim());
      setCategories(c => [...c, res[0]]);
      setNewCat("");
      toast("Catégorie ajoutée");
    } catch { toast("Cette catégorie existe déjà", "error"); }
    setAdding(false);
  };
  const del = async () => {
    setDelLoading(true);
    try { await api.deleteCategory(confirm.id); setCategories(c => c.filter(x => x.id !== confirm.id)); toast("Catégorie supprimée"); setConfirm(null); }
    catch { toast("Erreur lors de la suppression", "error"); }
    setDelLoading(false);
  };
  return (
    <div style={{ padding: "20px 16px 100px" }}>
      <Confirm open={!!confirm} message={`Supprimer la catégorie "${confirm?.name}" ?`} onYes={del} onNo={() => setConfirm(null)} loading={delLoading} />
      <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 22 }}>
        <button onClick={() => setPage("settings")} style={{ background: G.card, border: `1px solid ${G.border}`, color: G.text, borderRadius: 12, width: 40, height: 40, fontSize: 18, cursor: "pointer" }}>←</button>
        <h1 style={{ fontFamily: "'Bebas Neue',sans-serif", fontWeight: 400, fontSize: 26, letterSpacing: "0.05em" }}>CATÉGORIES</h1>
      </div>
      <Card style={{ marginBottom: 16 }}>
        <div style={{ display: "flex", gap: 10 }}>
          <input value={newCat} onChange={e => setNewCat(e.target.value)} onKeyDown={e => e.key === "Enter" && add()} placeholder="Nouvelle catégorie…" style={{ flex: 1, background: G.surface, border: `1px solid ${G.border}`, borderRadius: 10, padding: "11px 14px", color: G.text, fontSize: 14 }} />
          <Btn onClick={add} sm loading={adding}>+ Ajouter</Btn>
        </div>
      </Card>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {categories.map(c => (
          <Card key={c.id} style={{ padding: 14 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span style={{ fontWeight: 600, fontSize: 15 }}>📂 {c.name}</span>
              <button onClick={() => setConfirm(c)} style={{ background: "rgba(239,68,68,0.08)", border: "1px solid rgba(239,68,68,0.2)", color: G.danger, borderRadius: 8, padding: "6px 12px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>Supprimer</button>
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
};

// ─── Settings ────────────────────────────────────────────────────────────────
const Settings = ({ user, onLogout, setPage }) => (
  <div style={{ padding: "20px 16px 100px" }}>
    <h1 style={{ fontFamily: "'Bebas Neue',sans-serif", fontWeight: 400, fontSize: 26, letterSpacing: "0.05em", marginBottom: 22 }}>PARAMÈTRES</h1>
    <Card style={{ marginBottom: 14 }}>
      <div style={{ display: "flex", gap: 16, alignItems: "center", marginBottom: 20 }}>
        <div style={{ width: 58, height: 58, borderRadius: 18, background: G.greenSoft, border: `1px solid ${G.border}`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 28 }}>{user.role === "admin" ? "👑" : "🧑‍💼"}</div>
        <div>
          <div style={{ fontWeight: 700, fontSize: 18 }}>{user.name}</div>
          <div style={{ color: G.muted, fontSize: 13, marginBottom: 4 }}>@{user.username}</div>
          <Badge>{user.role === "admin" ? "Admin" : "Vendeur"}</Badge>
        </div>
      </div>
      <div style={{ borderTop: `1px solid ${G.border}`, paddingTop: 16 }}>
        {[["📞", "Téléphone", "+221 78 458 1111"], ["📧", "Email", "infos@dakarvapes.com"], ["🏪", "Boutique", "Dakar Vapes — Dakar, Sénégal"]].map(([ic, lbl, val]) => (
          <div key={lbl} style={{ display: "flex", gap: 12, alignItems: "center", marginBottom: 12 }}>
            <span style={{ fontSize: 20 }}>{ic}</span>
            <div><div style={{ fontSize: 11, color: G.muted, fontWeight: 700, textTransform: "uppercase" }}>{lbl}</div><div style={{ fontSize: 14 }}>{val}</div></div>
          </div>
        ))}
      </div>
    </Card>
    {user.role === "admin" && (
      <Card style={{ marginBottom: 14 }}>
        <h3 style={{ fontFamily: "'Bebas Neue',sans-serif", fontWeight: 400, fontSize: 18, letterSpacing: "0.05em", marginBottom: 14 }}>ADMINISTRATION</h3>
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          <Btn variant="ghost" onClick={() => setPage("categories")} full>📂 Gérer les catégories</Btn>
          <Btn variant="ghost" onClick={() => setPage("users")} full>👥 Gérer l'équipe</Btn>
        </div>
      </Card>
    )}
    <Btn variant="danger" onClick={onLogout} full>Se déconnecter</Btn>
  </div>
);

// ─── App Root ─────────────────────────────────────────────────────────────────
export default function App() {
  useEffect(() => { injectStyles(); }, []);
  const [stage, setStage] = useState("age");
  const [user, setUser] = useState(null);
  const [page, setPage] = useState("dashboard");
  const [editProduct, setEditProduct] = useState(null);
  const [invoice, setInvoice] = useState(null);
  const [appLoading, setAppLoading] = useState(false);
  const [users, setUsers] = useState([]);
  const [products, setProducts] = useState([]);
  const [sales, setSales] = useState([]);
  const [categories, setCategories] = useState([]);

  const loadAll = async () => {
    setAppLoading(true);
    try {
      const [u, p, s, c] = await Promise.all([api.getUsers(), api.getProducts(), api.getSales(), api.getCategories()]);
      setUsers(u); setProducts(p); setSales(s); setCategories(c);
    } catch { toast("Erreur de connexion à la base de données", "error"); }
    setAppLoading(false);
  };

  const handleLogin = async (u) => {
    setUser(u);
    setStage("loading");
    await loadAll();
    setPage(u.role === "admin" ? "dashboard" : "pos");
    setStage("app");
  };

  const logout = () => { setUser(null); setStage("login"); setPage("dashboard"); };

  const renderPage = () => {
    if (page === "dashboard") return <Dashboard user={user} products={products} sales={sales} />;
    if (page === "inventory") return <Inventory products={products} setProducts={setProducts} categories={categories} user={user} setPage={setPage} setEditProduct={setEditProduct} />;
    if (page === "addproduct") return <AddProduct setProducts={setProducts} editProduct={editProduct} categories={categories} setPage={setPage} />;
    if (page === "pos") return <POS products={products} setProducts={setProducts} user={user} setSales={setSales} categories={categories} setPage={setPage} setInvoice={setInvoice} />;
    if (page === "sales") return <SalesHistory sales={sales} setPage={setPage} setInvoice={setInvoice} />;
    if (page === "invoice") return <Invoice invoice={invoice} setPage={setPage} />;
    if (page === "users") return <UserMgmt users={users} setUsers={setUsers} currentUser={user} />;
    if (page === "categories") return <CatMgmt categories={categories} setCategories={setCategories} setPage={setPage} />;
    if (page === "settings") return <Settings user={user} onLogout={logout} setPage={setPage} />;
    return null;
  };

  if (stage === "age") return <><AgeVerification onConfirm={() => setStage("login")} /><Toast /></>;
  if (stage === "login") return <><Login onLogin={handleLogin} /><Toast /></>;
  if (stage === "loading") return (
    <div style={{ minHeight: "100vh", background: G.bg, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 24 }}>
      <Logo height={80} />
      <Spinner size={40} />
      <p style={{ color: G.muted, fontSize: 14 }}>Chargement des données…</p>
    </div>
  );

  return (
    <div style={{ maxWidth: 480, margin: "0 auto", minHeight: "100vh" }}>
      <div style={{ position: "sticky", top: 0, background: `${G.bg}ee`, backdropFilter: "blur(14px)", borderBottom: `1px solid ${G.border}`, padding: "10px 16px", display: "flex", justifyContent: "space-between", alignItems: "center", zIndex: 50 }}>
        <Logo height={38} />
        <button onClick={() => setPage("settings")} style={{ background: G.card, border: `1px solid ${G.border}`, borderRadius: 12, padding: "6px 14px", color: G.text, fontSize: 13, fontWeight: 600, cursor: "pointer", display: "flex", alignItems: "center", gap: 8 }}>
          {user.role === "admin" ? "👑" : "🧑‍💼"} {user.name}
        </button>
      </div>
      <div className="fade-up">{appLoading ? <Loading /> : renderPage()}</div>
      <NavBar page={page} setPage={setPage} role={user.role} />
      <Toast />
    </div>
  );
}
